import{_ as e,o as t,c as o,ai as c}from"./chunks/framework.DAbPic9L.js";const T=JSON.parse('{"title":"网络传输协议面试题集","description":"","frontmatter":{},"headers":[],"relativePath":"interviews/network.md","filePath":"interviews/network.md","lastUpdated":1778735525000}'),r={name:"interviews/network.md"};function a(l,d,i,h,n,p){return t(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="网络传输协议面试题集" tabindex="-1">网络传输协议面试题集 <a class="header-anchor" href="#网络传输协议面试题集" aria-label="Permalink to &quot;网络传输协议面试题集&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="如何理解-osi-七层模型" tabindex="-1">如何理解 OSI 七层模型 <a class="header-anchor" href="#如何理解-osi-七层模型" aria-label="Permalink to &quot;如何理解 OSI 七层模型&quot;">​</a></h2><ol><li>物理层：传输比特流。</li><li>数据链路层：将比特流封装成数据帧，进行差错控制。</li><li>网络层：路由选择，逻辑寻址(<code>IP</code>)。</li><li>传输层：端到端的连接通信，可靠传输(<code>TCP</code>)，广播传输(<code>UDP</code>)。</li><li>会话层：建立、管理会话(<code>RPC</code>)。</li><li>表示层：数据格式转换(<code>XML</code>)，加密解密(<code>SSL/TLS</code>)。</li><li>应用层：各种应用层协议(<code>HTTP</code>)，文件传输(<code>FTP</code>)。</li></ol><h2 id="如何理解-tcp-ip-四层模型" tabindex="-1">如何理解 TCP/IP 四层模型 <a class="header-anchor" href="#如何理解-tcp-ip-四层模型" aria-label="Permalink to &quot;如何理解 TCP/IP 四层模型&quot;">​</a></h2><ol><li>网络接口层：对应<code>OSI</code>模型的物理层、数据链路层。</li><li>网际层：对应<code>OSI</code>模型的网络层；核心是<code>IP</code>协议。</li><li>传输层：对应<code>OSI</code>模型的传输层；核心是<code>TCP</code>协议和<code>UDP</code>协议。</li><li>应用层：对应<code>OSI</code>模型的应用层；核心是<code>HTTP</code>协议。</li></ol><h2 id="如何理解-arp-协议" tabindex="-1">如何理解 ARP 协议 <a class="header-anchor" href="#如何理解-arp-协议" aria-label="Permalink to &quot;如何理解 ARP 协议&quot;">​</a></h2><p><code>ARP</code>协议是地址解析协议，用于数据链路层数据包根据<code>IP</code>地址获取<code>MAC</code>地址。</p><p><code>ARP</code>发起广播请求，局域网内所有主机都会收到请求，但只有<code>IP</code>地址匹配的主机会响应<code>ARP</code>请求作出应答，并在应答包中包含自己的<code>MAC</code>地址。</p><h2 id="如何理解-dns-工作原理" tabindex="-1">如何理解 DNS 工作原理 <a class="header-anchor" href="#如何理解-dns-工作原理" aria-label="Permalink to &quot;如何理解 DNS 工作原理&quot;">​</a></h2><p><code>DNS</code>负责将网站域名转换为<code>IP</code>地址。其工作流程遵循分层查询、缓存加速、递归+迭代结合的机制。</p><p><strong>域名解析过程</strong></p><ol><li>客户端发送请求（网站域名），操作系统查询本地<code>DNS</code>缓存（浏览器缓存、操作系统<code>hosts</code>文件、操作系统<code>DNS</code>缓存）；存在则直接返回<code>IP</code>；否则向配置的<code>DNS</code>解析器查询缓存，找不到就（向运营商：<code>114.114.114.114</code>，公共：<code>8.8.8.8</code>）发送递归查询请求。</li><li>递归解析器迭代查询根服务器，根服务器返回顶级域名服务器的<code>IP</code>地址列表，并告知访问<code>TLD</code>服务器即可。</li><li>递归解析器迭代查询顶级域名服务器，<code>TLD</code>服务器返回权威服务器的<code>IP</code>地址列表，并告知访问权威服务器即可。</li><li>递归解析器迭代查询权威服务器，权威服务器查询自身存储的<code>DNS</code> 记录（如<code>A</code>记录：<code>IPv4</code>地址、<code>AAAA</code>记录：<code>IPv6</code>地址）,返回网站域名对应的<code>IP</code>地址。</li></ol><p>总结一句话：域名解析过程，通过<code>DNS</code>查询本地缓存记录（浏览器、操作系统、<code>DNS</code>缓存）,找不到就通过递归解析器迭代查询（根服务器、顶级域名服务器、权威服务器），最终返回网站域名对应的<code>IP</code>地址。</p><h2 id="如何理解-tcp-三次握手" tabindex="-1">如何理解 TCP 三次握手 <a class="header-anchor" href="#如何理解-tcp-三次握手" aria-label="Permalink to &quot;如何理解 TCP 三次握手&quot;">​</a></h2><p><code>TCP</code>三次握手发生在客户端与服务端建立的阶段过程。</p><p>通过双方同步序列号、确认号，协商连接参数，确认彼此收发能力，建立可靠连接。</p><p><strong>三次握手流程</strong></p><ul><li>客户端发送<code>SYN</code>包到服务端，并进入<code>SYN_SEND</code>状态。</li><li>服务端收到<code>SYN</code>包，发送<code>SYN+ACK</code>包到客户端，并进入<code>SYN_RECV</code>状态。</li><li>客户端收到<code>SYN+ACK</code>包，发送<code>ACK</code>包到服务端，并进入<code>ESTABLISHED</code>状态，连接建立完成。</li></ul><p><strong>为什么需要三次握手</strong></p><p>两次握手只能确认客户端发送能力和服务端收发能力，但无法确认客户端接收能力和服务端发送能力，会导致无效连接，造成资源浪费。</p><p>三次握手通过客户端和服务端的全量验证（同步序列号、确认号、连接参数），建立可靠连接。</p><h2 id="如何理解-tcp-四次挥手" tabindex="-1">如何理解 TCP 四次挥手 <a class="header-anchor" href="#如何理解-tcp-四次挥手" aria-label="Permalink to &quot;如何理解 TCP 四次挥手&quot;">​</a></h2><p><code>TCP</code>四次挥手发生在客户端与服务端断开的阶段过程。</p><p>通过主方发起关闭连接请求，对方确认收到关闭请求；对方发送已关闭连接请求，主方确认收到关闭请求，两端连接断开。</p><p><strong>四次挥手流程（主方-客户端，对方-服务端）</strong></p><ul><li>客户端发送<code>FIN</code>包到服务端，并进入<code>FIN_WAIT1</code>状态。</li><li>服务端收到<code>FIN</code>包，发送<code>ACK</code>包到客户端，并进入<code>CLOSE_WAIT</code>状态。</li><li>服务端发送<code>FIN</code>包到客户端，并进入<code>LAST_ACK</code>状态。</li><li>客户端收到<code>FIN</code>包，发送<code>ACK</code>包到服务端，连接断开。</li></ul><h2 id="如何理解-tcp-和-udp-区别" tabindex="-1">如何理解 TCP 和 UDP 区别 <a class="header-anchor" href="#如何理解-tcp-和-udp-区别" aria-label="Permalink to &quot;如何理解 TCP 和 UDP 区别&quot;">​</a></h2><p><code>TCP</code>和<code>UDP</code>都是传输层协议。</p><p><code>TCP</code>是面向连接的字节流传输方式，会经历三次握手、四次挥手过程，保证数据有序、完整、可靠传输；适用于数据完整场景。</p><p><code>UDP</code>是面向广播的数据报传输方式，以固定速率发送数据，不考虑网络状态、收发情况、数据完整性；适用于现场实时性场景。</p><p><strong>维度对比</strong></p><table tabindex="0"><thead><tr><th>对比维度</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接性</td><td>面向连接（需三次握手 / 四次挥手）</td><td>无连接（直接发送数据报）</td></tr><tr><td>可靠性 可靠（确认、重传、流量 / 拥塞控制）</td><td>不可靠（无确认、无重传）</td><td></td></tr><tr><td>数据形式</td><td>字节流（无边界，可拆分 / 合并）</td><td>数据报（有边界，独立传输）</td></tr><tr><td>头部开销</td><td>20~60 字节</td><td>8 字节</td></tr><tr><td>传输效率</td><td>低，延迟高</td><td>高，延迟极低</td></tr><tr><td>拥塞 / 流量控制</td><td>有</td><td>无</td></tr><tr><td>传输顺序</td><td>保证有序（按序列号重组）</td><td>不保证有序（可能乱序）</td></tr><tr><td>适用场景</td><td>要求数据完整、可靠的场景</td><td>要求实时性、轻量化的场景</td></tr></tbody></table><h2 id="如何理解-http-与-https-区别" tabindex="-1">如何理解 HTTP 与 HTTPS 区别 <a class="header-anchor" href="#如何理解-http-与-https-区别" aria-label="Permalink to &quot;如何理解 HTTP 与 HTTPS 区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td><strong>安全性</strong></td><td>明文传输，易被窃听</td><td>加密传输，安全可靠</td></tr><tr><td><strong>端口</strong></td><td>默认 80</td><td>默认 443</td></tr><tr><td><strong>证书</strong></td><td>不需要</td><td>需要 SSL/TLS 证书</td></tr><tr><td><strong>性能</strong></td><td>较快（无加密开销）</td><td>略慢（有加密解密开销）</td></tr><tr><td><strong>SEO</strong></td><td>搜索引擎排名劣势</td><td>Google 等优先收录</td></tr></tbody></table><p>重要区别：<code>HTTPS</code>在<code>HTTP</code>的基础上，通过<code>SSL/TLS</code>协议加密传输数据，增加了安全性。</p><h2 id="如何理解-cdn-工作原理" tabindex="-1">如何理解 CDN 工作原理 <a class="header-anchor" href="#如何理解-cdn-工作原理" aria-label="Permalink to &quot;如何理解 CDN 工作原理&quot;">​</a></h2><p><code>CDN</code>是内容分发网络，通过部署在各地的服务器缓存网站内容，提高网站的访问速度。</p><p>工作原理是通过将内容缓存到里用户最近的边缘节点服务器。当用户请求时，会通过最近节点获取资源，以减少网络延迟，提高加载速度，并减轻源站服务器的负载。</p><h2 id="如何理解负载均衡以及相关算法" tabindex="-1">如何理解负载均衡以及相关算法 <a class="header-anchor" href="#如何理解负载均衡以及相关算法" aria-label="Permalink to &quot;如何理解负载均衡以及相关算法&quot;">​</a></h2><p>负载均衡是通过将请求分发到集群网络服务器，以优化资源利用绿、最大化吞吐量、最小化响应时间等，确保容错性和可用性。</p><p>创建负载均衡集群有两种方式：</p><ol><li>硬件负载均衡：通过硬件设备如交换机、路由器等实现负载均衡。</li><li>软件负载均衡：通过软件实现负载均衡，如<code>Nginx</code>、<code>HAProxy</code>等。</li></ol><p>常见的负载均衡算法有：</p><ol><li>轮询：将请求轮流分配到集群中每台服务器。</li><li>加权轮询：根据服务器的性能指标，按权重分配请求到性能更好的服务器。</li><li>最少连接：将新请求分发到最少活动的服务器。</li><li><code>IP</code>哈希：根据<code>IP</code>地址哈希分配请求到服务器，解决<code>session</code>共享问题。</li></ol><h2 id="如何理解-http-协议的请求方法" tabindex="-1">如何理解 HTTP 协议的请求方法 <a class="header-anchor" href="#如何理解-http-协议的请求方法" aria-label="Permalink to &quot;如何理解 HTTP 协议的请求方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>请求方法</th><th>内容描述</th></tr></thead><tbody><tr><td>GET</td><td>获取实体资源</td></tr><tr><td>POST</td><td>创建实体资源</td></tr><tr><td>DELETE</td><td>删除实体资源</td></tr><tr><td>PATCHE</td><td>局部更新资源</td></tr><tr><td>PUT</td><td>全量更新资源</td></tr><tr><td>HEAD</td><td>获取报文首部</td></tr><tr><td>OPTIONS</td><td>询问支持的方法</td></tr></tbody></table><h2 id="列举-http-常用状态码" tabindex="-1">列举 HTTP 常用状态码 <a class="header-anchor" href="#列举-http-常用状态码" aria-label="Permalink to &quot;列举 HTTP 常用状态码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态码</th><th>作用描述</th></tr></thead><tbody><tr><td>200</td><td>请求成功(获取或创建场景)</td></tr><tr><td>204</td><td>请求成功(更新、删除等无实体返回场景)</td></tr><tr><td>301</td><td>资源永久重定向</td></tr><tr><td>302</td><td>资源临时重定向</td></tr><tr><td>304</td><td>沿用客户端缓存(强缓存或协商缓存)</td></tr><tr><td>400</td><td>客户端请求错误(参数错误)</td></tr><tr><td>401</td><td>未提供授权认证(未登录或未授权场景)</td></tr><tr><td>403</td><td>禁止访问该资源(没有权限访问场景)</td></tr><tr><td>404</td><td>请求资源未找到</td></tr><tr><td>409</td><td>资源冲突(创建时唯一冲突)</td></tr><tr><td>500</td><td>服务器内部错误</td></tr><tr><td>502</td><td>网关错误(上游不可用)</td></tr><tr><td>503</td><td>服务不可用(过载或维护)</td></tr></tbody></table><h2 id="如何理解-restful-api-设计规范" tabindex="-1">如何理解 RESTful API 设计规范 <a class="header-anchor" href="#如何理解-restful-api-设计规范" aria-label="Permalink to &quot;如何理解 RESTful API 设计规范&quot;">​</a></h2><ul><li>资源：<code>URL</code>定位的资源，命名规则为<code>名词</code>；动态传值资源索引（<code>id</code>）。</li><li>表现层：请求响应返回的具体格式；如<code>JSON</code>、<code>XML</code>等。</li><li>状态转移：根据请求方法明确资源操作的阶段；如<code>GET</code>为资源获取、<code>POST</code>为资源创建、<code>PUT</code>为资源更新、<code>DELETE</code>为资源删除。</li><li>无状态通信：每个请求都携带完整上下文（<code>Token</code>），服务器不保存客户端会话状态。</li></ul><p>掌握好<code>RESTful API</code>，网络请求接口的自描述性，符合开发者的心理模型；可减少前后端协作成本，提升开发效率。</p><h2 id="如何理解访问浏览器的-url-发生了什么" tabindex="-1">如何理解访问浏览器的 URL 发生了什么 <a class="header-anchor" href="#如何理解访问浏览器的-url-发生了什么" aria-label="Permalink to &quot;如何理解访问浏览器的 URL 发生了什么&quot;">​</a></h2><ol><li><p><code>URL</code>解析：对<code>URL</code>语法解析并标准化。固定协议、域名、端口、路径、查询参数、片段内容等参数字段；并标准化字段内容（自动补全）。</p></li><li><p>网站域名解析：通过<code>DNS</code>解析网站域名为<code>IP</code>地址；经过查询本地缓存查询（浏览器、系统文件、<code>DNS</code>配置表），和迭代查询（运营商、根服务器、顶级服务器、请权威服务器）返回网站<code>IP</code>地址。</p></li><li><p><code>TCP</code>三次握手建立连接：客户端发送<code>SYN</code>包到服务端，并进入<code>SYN_SEND</code>状态；服务端收到<code>SYN</code>包，发送<code>SYN+ACK</code>包到客户端，并进入<code>SYN_RECV</code>状态；客户端收到<code>SYN+ACK</code>包，发送<code>ACK</code>包到服务端，并进入<code>ESTABLISHED</code>状态，连接建立完成。若网站使用<code>HTTPS</code>，会经历<code>SSL/TLS</code>握手建立加密通道过程。</p></li><li><p>发送<code>HTTP/HTTPS</code>请求：浏览器解析<code>URL</code>路径、参数，经过<code>TLS</code>加密传输，固定请求行格式（方法、路径、请求版本）、请求头（<code>Host</code>、<code>User-Agent</code>、<code>Cookie</code>等）、请求体（<code>POST/PUT</code>等方法有，<code>GET</code>无）发送<code>HTTP</code>请求到服务端。</p></li><li><p>服务器处理请求并返回响应：在链路层剥离<code>MAC</code>头部，取出<code>IP</code>数据报；在网络层剥离<code>IP</code>头部，取出<code>TCP</code>分段经过<code>TLS</code>解密，重组为完整<code>HTTP</code>报文。通过<code>Web</code>访问器解析请求参数，调用服务处理请求，并生成响应报文；响应报文包含状态行（请求版本、状态码、状态描述）、响应头（<code>Content-Type</code>、<code>Content-Length</code>、<code>Cache-Control</code>等）、响应体（服务器的返回内容-实体）。</p></li><li><p>浏览器解封并校验响应内容：网络一端经过多层到达传输层，解析获得<code>TCP</code>分段，并经过<code>TLS</code>解密，重组为完整<code>HTTP</code>报文，校验序列号、确认号、确保数据完整性；对缺失分段请求重传。</p></li><li><p>传输层关闭连接：客户端发送<code>FIN</code>包到服务端，并进入<code>FIN_WAIT1</code>状态；服务端收到<code>FIN</code>包，发送<code>ACK</code>包到客户端，并进入<code>CLOSE_WAIT</code>状态；服务端发送<code>FIN</code>包到客户端，并进入<code>LAST_ACK</code>状态；客户端收到<code>FIN</code>包，发送<code>ACK</code>包到服务端，连接断开。</p></li><li><p>浏览器渲染页面：浏览器解析<code>HTML</code>内容，并渲染页面，显示给用户；详细过程参见<a href="/blog/interviews/browser.html">客户端浏览器面试题集</a>章节。</p></li></ol>',55)])])}const s=e(r,[["render",a]]);export{T as __pageData,s as default};
